SELECT AVG(c.GNP) AS mean_gnp, SUM(c.Population) AS total_population
FROM country c
WHERE c.Name LIKE '%United States%' OR c.Name LIKE '%US%' OR c.Name LIKE '%USA%' OR c.GovernmentForm LIKE '%territory%' OR c.GovernmentForm LIKE '%dependency%';

