SELECT DISTINCT h.name
FROM Highschooler h
WHERE EXISTS (
    SELECT 1 FROM Friend f WHERE f.student_id = h.ID
) AND EXISTS (
    SELECT 1 FROM Likes l WHERE l.liked_id = h.ID
);

